action.code:
lfs_size_t cmpsize = size;
if (cmpsize > hint) {
    cmpsize = hint;
}

int res = lfs_bd_flush(lfs, pcache);
if (res) {
    return res;
}

const uint8_t *data = static_cast<const uint8_t*>(buffer);
lfs_size_t tfs_off = 0;

while (tfs_off < size) {
    if (cmpsize == 0) {
        return LFS_ERR_CORRUPT;
    }

    lfs_size_t read = cmpsize;
    if (read > lfs->cfg->read_size) {
        read = lfs->cfg->read_size;
    }

    res = lfs->cfg->read(lfs->cfg, block, off + tfs_off, read, &data[tfs_off]);
    if (res) {
        return res;
    }

    tfs_off += read;
}

uint8_t *dat = const_cast<uint8_t*>(data);
lfs_size_t chunk = cmpsize;
if (chunk > (size - tfs_off)) {
    chunk = size - tfs_off;
}

res = lfs_bd_flush(lfs, rcache);
if (res) {
    return res;
}

if (chunk > 0) {
    int cmp = std::memcmp(dat, buffer, chunk);
    if (cmp != 0) {
        return cmp < 0 ? LFS_CMP_LT : LFS_CMP_GT;
    }
    tfs_off += chunk;
}

return LFS_CMP_EQ;
// END_CODE

